WITH enriched AS (SELECT id, store_id, product_id, last_restock, SUM(quantity) OVER (ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_quantity, ROW_NUMBER() OVER (PARTITION BY store_id, product_id ORDER BY last_restock DESC, id) seq_no, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock, id) seq_no_2, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY quantity, id) seq_no_3 FROM inventory), enriched_inventory AS (SELECT e.*, p.category, p.launch_date, p.cost FROM enriched e INNER JOIN products p ON e.product_id = p.id), metrics AS (SELECT *, LAG(cumulative_quantity) OVER (PARTITION BY product_id ORDER BY cost, id) prev_cumulative_quantity, LEAD(seq_no) OVER (PARTITION BY product_id ORDER BY cost, id) next_seq_no, LAG(seq_no) OVER (PARTITION BY product_id ORDER BY cost, id) prev_seq_no, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY cost, id) event_seq FROM enriched_inventory), joined AS (SELECT src.id, src.product_id, src.last_restock, src.seq_no, src.seq_no_2, src.seq_no_3, src.next_seq_no, src.prev_seq_no, b.cost AS product_cost FROM metrics src LEFT JOIN products b ON src.product_id = b.id WHERE b.stock_qty <= 282), enriched_inventory_2 AS (SELECT src.*, b.brand, b.category FROM joined src INNER JOIN products b ON src.product_id = b.id) SELECT category, next_seq_no, prev_seq_no, COUNT_IF(category = 'Home') AS home_events, COUNT(DISTINCT id) AS distinct_ids, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list, SUM(prev_seq_no) AS total_prev_seq_no, COUNT(*) AS row_count, SORT_ARRAY(COLLECT_SET(category)) AS category_list, PERCENT_RANK() OVER (PARTITION BY category ORDER BY COUNT(*) DESC) AS row_count_percent_rank FROM enriched_inventory_2 GROUP BY 1, 2, 3
